// AI Deep Time — data/milestones-a.js: milestones 1–17, eras E01–E06 (1943 to 2011), and the sources they cite.
// `t` = year + (dayOfYear-1)/365 (month precision → the 15th; year precision → mid-year). `numbers[].value` are display
// strings with `est` flags for estimates; `caveat` is non-null only when `confidence` is not "high". Plain ES5.
window.AIH = window.AIH || {};
(window.AIH.milestones = window.AIH.milestones || []).push(
  // ---------------------------------------------------------------- E01 · Dawn (1943–1955)
  {id: "M-1943-mcculloch-pitts", date: "1943-12", precision: "month", t: 1943.95, era: "E01",
   title: {en: "McCulloch–Pitts artificial neuron", uk: "Штучний нейрон Мак-Каллока і Піттса"},
   who: {en: "Warren S. McCulloch, Walter Pitts — University of Illinois College of Medicine / University of Chicago circle",
         uk: "Воррен Мак-Каллок, Волтер Піттс — Медичний коледж Університету Іллінойсу / коло дослідників Чиказького університету"},
   kind: "paper",
   what: {en: "McCulloch and Pitts treated a neuron as an all-or-none switch that fires when its excitatory inputs reach a threshold, and that any inhibitory input can veto. They proved that networks of these units can compute any logical expression, and that with a tape attached such a network is as powerful as a Turing machine.",
          uk: "Мак-Каллок і Піттс розглядали нейрон як перемикач «усе або нічого»: він спрацьовує, коли збуджувальні входи досягають порога, а будь-який гальмівний вхід може це заблокувати. Вони довели, що мережі з таких елементів можуть обчислити будь-який логічний вираз, а з приєднаною стрічкою така мережа не поступається машині Тюрінга."},
   why: {en: "This was the first mathematical \"artificial neuron\", and every later neural network descends from it. It also tied brain science to logic and to the new idea of computation. Its weights and thresholds were fixed by hand, so the units could not yet learn.",
         uk: "Це був перший математичний «штучний нейрон», і всі пізніші нейронні мережі походять від нього. Робота також пов'язала науку про мозок із логікою та новою ідеєю обчислення. Її ваги й пороги задавали вручну, тож елементи ще не вміли навчатися."},
   example: {en: "John von Neumann's \"First Draft of a Report on the EDVAC\" (1945), one of the founding designs of the stored-program computer, built its logic from \"E-elements\" modelled on McCulloch–Pitts neurons and credited the 1943 paper.",
             uk: "«Перший начерк звіту про EDVAC» Джона фон Неймана (1945), один із засадничих проєктів комп'ютера зі збереженою програмою, будував свою логіку з «E-елементів», змодельованих за нейронами Мак-Каллока і Піттса, і посилався на статтю 1943 року."},
   memorable: {en: "Pitts was 20 when the paper appeared and had no degree. According to biographical accounts, he had left home at 15 to attend lectures in Chicago and was living with McCulloch's family when they wrote it.",
               uk: "Коли стаття вийшла, Піттсу було 20 і він не мав диплома. За біографічними джерелами, у 15 років він пішов з дому, щоб слухати лекції в Чикаго, а на час написання статті жив у родині Мак-Каллока."},
   numbers: [
     {label: {en: "Learned parameters", uk: "Навчених параметрів"}, value: "0", note: {en: "weights and thresholds were set by hand", uk: "ваги й пороги задавали вручну"}, est: false},
     {label: {en: "Pages", uk: "Сторінок"}, value: "19", note: {en: "Bulletin of Mathematical Biophysics 5(4), December 1943", uk: "Bulletin of Mathematical Biophysics 5(4), грудень 1943"}, est: false},
     {label: {en: "Pitts's age at publication", uk: "Вік Піттса на час публікації"}, value: "20", note: {en: "he had no degree; biographical details rest on secondary sources", uk: "він не мав диплома; біографічні подробиці — за вторинними джерелами"}, est: false}
   ],
   arch: "ARCH-perceptron", significance: 5, confidence: "high", caveat: null,
   sources: ["S-R1-01", "S-R1-02"]},

  {id: "M-1950-turing-test", date: "1950-10", precision: "month", t: 1950.79, era: "E01",
   title: {en: "Turing's imitation game", uk: "«Гра в імітацію» Тюрінга"},
   who: {en: "Alan M. Turing — University of Manchester",
         uk: "Алан Тюрінг — Манчестерський університет"},
   kind: "paper",
   what: {en: "Turing replaced the question \"Can machines think?\" with a test, the imitation game: an interrogator questions a hidden human and a hidden machine by typed messages and tries to tell which is which. The paper also answered nine objections and proposed building a \"child machine\" and educating it, instead of programming an adult mind directly.",
          uk: "Тюрінг замінив запитання «Чи можуть машини мислити?» на тест — гру в імітацію: суддя листується з прихованою людиною і прихованою машиною й намагається визначити, хто є хто. Стаття також відповіла на дев'ять заперечень і запропонувала побудувати «машину-дитину» й виховати її, замість того щоб одразу програмувати дорослий розум."},
   why: {en: "It gave AI a behavioural definition of success and its best-known benchmark. Its section on learning machines anticipated machine learning.",
         uk: "Це дало ШІ поведінкове визначення успіху та його найвідоміший бенчмарк. Розділ про машини, що навчаються, передбачив машинне навчання."},
   example: {en: "In a pre-registered three-party test in 2025 (a preprint), using Turing's own five-minute format, GPT-4.5 with a persona prompt was judged to be the human 73% of the time. ELIZA (1966) was judged human 23% of the time (Jones & Bergen, UC San Diego).",
             uk: "У попередньо зареєстрованому тристоронньому тесті 2025 року (препринт), за власним п'ятихвилинним форматом Тюрінга, GPT-4.5 із промптом-персоною визнавали людиною у 73 % випадків. ELIZA (1966) вважали людиною у 23 % випадків (Джонс і Берген, Каліфорнійський університет у Сан-Дієго)."},
   memorable: {en: "Turing's bar was modest. The machine only had to fool the judge 30% of the time over five minutes, and he guessed that about 125 megabytes of memory would be enough. He called it the \"imitation game\", not the \"Turing test\".",
               uk: "Планка Тюрінга була скромною: машині досить було обдурити суддю в 30 % випадків за п'ять хвилин, а пам'яті, за його оцінкою, вистачило б близько 125 мегабайтів. Сам він називав це «грою в імітацію», а не «тестом Тюрінга»."},
   numbers: [
     {label: {en: "Predicted chance of a correct identification", uk: "Передбачений шанс правильного розпізнавання"}, value: "≤70%", note: {en: "for an average interrogator after five minutes of questioning, \"in about fifty years' time\" (≈2000)", uk: "для пересічного судді після п'яти хвилин запитань, «приблизно за п'ятдесят років» (≈2000)"}, est: false},
     {label: {en: "Storage Turing assumed, binary digits", uk: "Обсяг пам'яті за Тюрінгом, двійкових розрядів"}, value: "≈10⁹", note: {en: "about 125 MB", uk: "близько 125 МБ"}, est: false},
     {label: {en: "GPT-4.5 judged human (2025 study, preprint)", uk: "GPT-4.5 визнано людиною (дослідження 2025 року, препринт)"}, value: "73%", note: {en: "pre-registered three-party, five-minute test with a persona prompt; ELIZA scored 23%", uk: "попередньо зареєстрований тристоронній п'ятихвилинний тест із промптом-персоною; ELIZA — 23 %"}, est: false}
   ],
   arch: null, significance: 5, confidence: "high", caveat: null,
   sources: ["S-R1-07", "S-R1-08"]},

  // ---------------------------------------------------------------- E02 · Symbolic optimism and the perceptron (1956–1973)
  {id: "M-1956-dartmouth", date: "1956-06", precision: "month", t: 1956.45, era: "E02",
   title: {en: "Dartmouth names \"artificial intelligence\"", uk: "Дартмут дає назву «штучний інтелект»"},
   who: {en: "John McCarthy (Dartmouth), Marvin Minsky (Harvard), Nathaniel Rochester (IBM), Claude Shannon (Bell Labs); participants included Ray Solomonoff, Oliver Selfridge, Allen Newell and Herbert Simon",
         uk: "Джон Маккарті (Дартмут), Марвін Мінський (Гарвард), Натаніель Рочестер (IBM), Клод Шеннон (Bell Labs); серед учасників — Рей Соломонов, Олівер Селфрідж, Аллен Ньюелл і Герберт Саймон"},
   kind: "event",
   what: {en: "The organisers proposed a \"2 month, 10 man study of artificial intelligence\", based on the conjecture that \"every aspect of learning or any other feature of intelligence can in principle be so precisely described that a machine can be made to simulate it.\" The topics included language, abstraction, self-improvement and \"neuron nets\". The proposal is dated 31 August 1955; the workshop ran in summer 1956.",
          uk: "Організатори запропонували «двомісячне дослідження штучного інтелекту силами десяти людей», виходячи з припущення, що «кожен аспект навчання чи будь-яку іншу ознаку інтелекту можна в принципі описати настільки точно, що машину можна змусити це відтворити». Серед тем були мова, абстракція, самовдосконалення та «нейронні мережі». Пропозицію датовано 31 серпня 1955 року; семінар відбувся влітку 1956-го."},
   why: {en: "The workshop gave the field its name (McCarthy chose a neutral label, partly to stay clear of \"cybernetics\"), an agenda and a founding network of researchers. McCarthy went on to create LISP (begun 1958, published 1960), the main AI language in the US for three decades.",
         uk: "Семінар дав галузі назву (Маккарті обрав нейтральний термін, почасти щоб відмежуватися від «кібернетики»), порядок денний і засадниче коло дослідників. Згодом Маккарті створив LISP (розпочато 1958 року, опубліковано 1960-го) — головну мову ШІ у США впродовж трьох десятиліть."},
   example: {en: "Newell and Simon brought Logic Theorist, often called the first AI program. It proved 38 of the first 52 theorems in chapter 2 of Whitehead and Russell's Principia Mathematica, and its proof of theorem 2.85 was more elegant than the original.",
             uk: "Ньюелл і Саймон привезли Logic Theorist, яку часто називають першою програмою ШІ. Вона довела 38 із перших 52 теорем другого розділу «Principia Mathematica» Вайтгеда і Рассела, а її доведення теореми 2.85 було елегантнішим за оригінал."},
   memorable: {en: "In January 1956 Simon told a class: \"Over Christmas, Al Newell and I invented a thinking machine.\" Logic Theorist was built from late 1955 and hand-simulated before Dartmouth, where it got a lukewarm reception.",
               uk: "У січні 1956 року Саймон сказав студентам: «На Різдво ми з Елом Ньюеллом винайшли мислячу машину». Logic Theorist створювали з кінця 1955 року й прогнали вручну ще до Дартмута, де її зустріли стримано."},
   numbers: [
     {label: {en: "Rockefeller Foundation grant", uk: "Грант Фонду Рокфеллера"}, value: "$7,500", note: {en: "of $13,500 requested (archival histories, Kline 2011)", uk: "із запитаних 13 500 доларів (за архівними дослідженнями, Клайн 2011)"}, est: false},
     {label: {en: "Duration, weeks", uk: "Тривалість, тижнів"}, value: "≈8", note: {en: "about 18 June to 17 August 1956, from Solomonoff's notes; attendance was fluid", uk: "приблизно з 18 червня до 17 серпня 1956 р., за нотатками Соломонова; склад учасників постійно змінювався"}, est: true},
     {label: {en: "Theorems proved by Logic Theorist", uk: "Теорем, доведених Logic Theorist"}, value: "38 / 52", note: {en: "of the first 52 theorems in chapter 2 of Principia Mathematica", uk: "із перших 52 теорем другого розділу Principia Mathematica"}, est: false},
     {label: {en: "Names on McCarthy's later list", uk: "Імен у пізнішому списку Маккарті"}, value: "47", note: {en: "participants and interested people", uk: "учасники та зацікавлені особи"}, est: false}
   ],
   arch: "ARCH-symbolic", significance: 5, confidence: "high", caveat: null,
   sources: ["S-R1-09", "S-R1-10", "S-R1-11", "S-R1-12", "S-R1-13", "S-R1-14"]},

  {id: "M-1958-perceptron", date: "1958-07-07", precision: "day", t: 1958.51, era: "E02",
   title: {en: "Rosenblatt's Perceptron", uk: "Перцептрон Розенблатта"},
   who: {en: "Frank Rosenblatt — Cornell Aeronautical Laboratory (Buffalo, NY), funded by the US Office of Naval Research",
         uk: "Френк Розенблатт — Корнельська аеронавігаційна лабораторія (Баффало, штат Нью-Йорк), за кошти Управління військово-морських досліджень США"},
   kind: "architecture",
   what: {en: "The perceptron learns to classify patterns by adjusting its weights whenever it makes a mistake. It was first simulated on an IBM 704. The Mark I hardware fed a 20×20 photocell \"retina\" through fixed random wiring to 512 association units and on to 8 response units; its learned weights were motor-driven potentiometers.",
          uk: "Перцептрон вчиться класифікувати образи, підлаштовуючи ваги щоразу, коли помиляється. Спершу його змоделювали на IBM 704. Апаратний Mark I передавав сигнал із «сітківки» з фотоелементів 20×20 через фіксовані випадкові з'єднання на 512 асоціативних елементів і далі на 8 вихідних; його навчені ваги були потенціометрами з моторним приводом."},
   why: {en: "It was the first machine to learn from examples instead of being programmed, and the direct ancestor of today's neural networks. It also produced AI's first hype cycle.",
         uk: "Це була перша машина, яка навчалася на прикладах замість програмування, і прямий предок сьогоднішніх нейронних мереж. Вона ж породила перший цикл ажіотажу навколо ШІ."},
   example: {en: "At the July 1958 demonstration the room-sized, 5-ton IBM 704 learned after 50 trials to tell cards marked on the left from cards marked on the right. The New York Times headline was \"New Navy Device Learns by Doing\". The Mark I hardware itself was first shown publicly on 23 June 1960.",
             uk: "На демонстрації в липні 1958 року п'ятитонний IBM 704 завбільшки з кімнату після 50 спроб навчився відрізняти картки з позначкою ліворуч від карток із позначкою праворуч. Заголовок New York Times: «Новий пристрій ВМС вчиться на практиці». Сам апаратний Mark I уперше показали публічно 23 червня 1960 року."},
   memorable: {en: "The Times reported that the Navy expected the device to \"walk, talk, see, write, reproduce itself and be conscious of its existence.\"",
               uk: "Times писала, що ВМС очікують від пристрою, що він «ходитиме, говоритиме, бачитиме, писатиме, відтворюватиме себе й усвідомлюватиме своє існування»."},
   numbers: [
     {label: {en: "Photocell inputs (Mark I)", uk: "Фотоелементів на вході (Mark I)"}, value: "400", note: {en: "a 20×20 retina, 512 association units, 8 response units (unit counts from secondary sources)", uk: "сітківка 20×20, 512 асоціативних і 8 вихідних елементів (кількості — за вторинними джерелами)"}, est: false},
     {label: {en: "Parameters", uk: "Параметри"}, value: "≈1,000", note: {en: "Epoch AI estimate; the number of adjustable weights varied between configurations", uk: "оцінка Epoch AI; кількість регульованих ваг різнилася між конфігураціями"}, est: true},
     {label: {en: "Training compute", uk: "Обчислення для навчання"}, value: "~10⁶ FLOP", note: {en: "reconstructed est. (Epoch AI): about 7×10⁵ FLOP, digitised from OpenAI's 2018 \"AI and Compute\" chart", uk: "реконструйована оцінка (Epoch AI): близько 7×10⁵ FLOP, оцифровано з графіка OpenAI «AI and Compute» 2018 року"}, est: true},
     {label: {en: "Trials to learn left from right", uk: "Спроб, щоб відрізнити ліве від правого"}, value: "50", note: {en: "July 1958 simulation on a 5-ton IBM 704; ONR funding about $10,000 in 1959, rising to about $153,000 by 1961 (secondary)", uk: "симуляція в липні 1958 року на п'ятитонному IBM 704; фінансування ONR — близько 10 000 доларів у 1959 році й до 153 000 у 1961-му (за вторинними джерелами)"}, est: false}
   ],
   arch: "ARCH-perceptron", significance: 5, confidence: "high", caveat: null,
   sources: ["S-R1-15", "S-R1-16", "S-R1-17", "S-R1-18", "S-R1-19"]},

  {id: "M-1966-eliza", date: "1966-01", precision: "month", t: 1966.04, era: "E02",
   title: {en: "ELIZA, the first chatbot", uk: "ELIZA, перший чат-бот"},
   who: {en: "Joseph Weizenbaum — MIT",
         uk: "Джозеф Вейценбаум — MIT"},
   kind: "system",
   what: {en: "ELIZA scanned typed input for keywords and used script rules to turn it into a reply. Its famous DOCTOR script imitated a Rogerian psychotherapist by reflecting the user's statements back as questions. It understood nothing.",
          uk: "ELIZA шукала в надрукованому тексті ключові слова й за правилами сценарію перетворювала його на відповідь. Її знаменитий сценарій DOCTOR імітував психотерапевта роджерівської школи, повертаючи висловлювання користувача у формі запитань. Вона нічого не розуміла."},
   why: {en: "ELIZA was the first widely known conversational program. It revealed the \"ELIZA effect\", the tendency to credit fluent text with understanding, and turned Weizenbaum into a leading critic of AI (\"Computer Power and Human Reason\", 1976). The same question returned with chatbots in 2022.",
         uk: "ELIZA стала першою широко відомою діалоговою програмою. Вона виявила «ефект Елізи» — схильність приписувати розуміння будь-якому зв'язному тексту — і зробила Вейценбаума одним із головних критиків ШІ («Computer Power and Human Reason», 1976). Те саме запитання повернулося з чат-ботами 2022 року."},
   example: {en: "Users talked to DOCTOR by teletype on MIT's CTSS time-sharing system, which ran on an IBM 7094. A descendant still ships in GNU Emacs as \"M-x doctor\".",
             uk: "Користувачі спілкувалися з DOCTOR через телетайп у системі з розподілом часу CTSS в MIT, що працювала на IBM 7094. Її нащадок досі входить до GNU Emacs як команда «M-x doctor»."},
   memorable: {en: "Weizenbaum's own secretary asked him to leave the room so she could talk to ELIZA in private (as he told it in 1976).",
               uk: "Власна секретарка Вейценбаума попросила його вийти з кімнати, щоб поговорити з ELIZA наодинці (за його ж розповіддю 1976 року)."},
   numbers: [
     {label: {en: "Developed at MIT", uk: "Розроблено в MIT"}, value: "1964–1966", note: {en: "written in MAD-SLIP; published in Communications of the ACM, January 1966", uk: "написано мовою MAD-SLIP; опубліковано в Communications of the ACM у січні 1966"}, est: false},
     {label: {en: "Share of the 1965 code in the 2024 reconstruction", uk: "Частка коду 1965 року в реконструкції 2024-го"}, value: "≈96%", note: {en: "the original source was found in MIT's archives in 2021; the reconstruction reproduced the 1966 conversations (secondary sources)", uk: "оригінальний код знайшли в архівах MIT у 2021 році; реконструкція відтворила діалоги 1966 року (за вторинними джерелами)"}, est: false},
     {label: {en: "Judged human in the 2025 Turing test (preprint)", uk: "Визнано людиною в тесті Тюрінга 2025 року (препринт)"}, value: "23%", note: {en: "Jones & Bergen, five-minute three-party format; GPT-4.5 with a persona prompt scored 73%", uk: "Джонс і Берген, тристоронній п'ятихвилинний формат; GPT-4.5 із промптом-персоною — 73 %"}, est: false}
   ],
   arch: "ARCH-symbolic", significance: 4, confidence: "high", caveat: null,
   sources: ["S-R1-22", "S-R1-23", "S-R1-08"]},

  {id: "M-1969-perceptrons-book", date: "1969", precision: "year", t: 1969.50, era: "E02",
   title: {en: "Minsky & Papert's Perceptrons", uk: "«Перцептрони» Мінського і Пейперта"},
   who: {en: "Marvin Minsky, Seymour Papert — MIT",
         uk: "Марвін Мінський, Сеймур Пейперт — MIT"},
   kind: "paper",
   what: {en: "The book is a rigorous mathematical analysis of perceptrons with a single adjustable layer, in which each first-layer unit sees only a limited part of the input. It proved that such machines cannot compute \"global\" properties such as parity (XOR is parity on two inputs) or whether a figure is connected, unless some unit is connected to the whole input.",
          uk: "Книжка — строгий математичний аналіз перцептронів з одним налаштовуваним шаром, у яких кожен елемент першого шару бачить лише обмежену частину входу. Вона довела, що такі машини не можуть обчислити «глобальні» властивості, як-от парність (XOR — це парність на двох входах) чи зв'язність фігури, якщо жоден елемент не під'єднаний до всього входу."},
   why: {en: "It was widely read as proof that neural networks were a dead end. Together with funding shifting to symbolic AI and Rosenblatt's death in 1971, it contributed to silencing neural-network research for over a decade; historians still disagree about how large its own effect was. Networks with more layers could represent XOR. What was missing was a practical way to train them, which arrived with backpropagation in 1986.",
         uk: "Її широко сприйняли як доказ того, що нейронні мережі — глухий кут. Разом із переходом фінансування до символьного ШІ та смертю Розенблатта 1971 року вона сприяла тому, що дослідження нейронних мереж замовкли більш ніж на десятиліття; історики досі сперечаються, наскільки великим був саме її вплив. Мережі з більшою кількістю шарів могли представити XOR. Бракувало практичного способу їх навчати, і він з'явився 1986 року зі зворотним поширенням помилки."},
   example: {en: "The perceptron programmes faded after 1969. ARPA had already declined to fund Rosenblatt, so his work depended on the Office of Naval Research. The revival had to wait for Hopfield (1982) and backpropagation (1986). Even the 1988 expanded edition called the multilayer extension \"sterile\".",
             uk: "Після 1969 року перцептронні програми згасли. ARPA ще раніше відмовилося фінансувати Розенблатта, тож його робота залежала від Управління військово-морських досліджень. Відродження довелося чекати до Гопфілда (1982) і зворотного поширення помилки (1986). Навіть розширене видання 1988 року назвало багатошарове узагальнення «безплідним»."},
   memorable: {en: "Minsky and Rosenblatt had attended the Bronx High School of Science a year apart, and later argued loudly at conferences while staying on friendly terms.",
               uk: "Мінський і Розенблатт навчалися в Бронкській науковій школі з різницею в рік, а згодом гучно сперечалися на конференціях, зберігаючи приятельські стосунки."},
   numbers: [
     {label: {en: "Chapters", uk: "Розділів"}, value: "13", note: {en: "MIT Press, 1969; corrected printing 1972; expanded edition 1988", uk: "MIT Press, 1969; виправлений наклад 1972; розширене видання 1988"}, est: false},
     {label: {en: "Inputs in XOR (parity)", uk: "Входів у XOR (парність)"}, value: "2", note: {en: "single-layer perceptrons with locally connected units cannot learn parity or connectedness", uk: "одношарові перцептрони з локально з'єднаними елементами не можуть вивчити парність чи зв'язність"}, est: false}
   ],
   arch: "ARCH-perceptron", significance: 4, confidence: "high", caveat: null,
   sources: ["S-R1-24", "S-R1-25", "S-R1-18"]},

  {id: "M-1973-lighthill", date: "1973", precision: "year", t: 1973.50, era: "E02",
   title: {en: "Lighthill Report and the first AI winter", uk: "Звіт Лайтгілла і перша «зима ШІ»"},
   who: {en: "Sir James Lighthill — Cambridge University, for the UK Science Research Council; in the US, DARPA",
         uk: "Сер Джеймс Лайтгілл — Кембриджський університет, на замовлення Ради наукових досліджень Великої Британії; у США — DARPA"},
   kind: "policy",
   what: {en: "Lighthill concluded that \"in no part of the field have the discoveries made so far produced the major impact that was then promised.\" He blamed the \"combinatorial explosion\": methods that worked on toy problems blew up on real ones. He judged general-purpose robotics, the \"bridge\" between automation and brain science, a failure.",
          uk: "Лайтгілл дійшов висновку, що «в жодній частині галузі зроблені дотепер відкриття не дали того великого ефекту, який тоді обіцяли». Він звинуватив «комбінаторний вибух»: методи, що працювали на іграшкових задачах, розвалювалися на справжніх. Універсальну робототехніку — «міст» між автоматизацією та наукою про мозок — він визнав провалом."},
   why: {en: "The Science Research Council ended AI support at most UK universities. In the US, the 1969 Mansfield Amendment had already pushed DARPA towards mission-oriented work, and DARPA cut undirected AI funding in 1973–74. Together these mark the start of the first AI winter (E03, about 1974–1980): a funding winter, not a research halt.",
         uk: "Рада наукових досліджень припинила підтримку ШІ в більшості британських університетів. У США поправка Менсфілда 1969 року вже підштовхнула DARPA до прикладних робіт, і в 1973–74 роках DARPA скоротила фінансування пошукових досліджень ШІ. Разом це позначає початок першої «зими ШІ» (E03, приблизно 1974–1980) — зими фінансування, а не зупинки досліджень."},
   example: {en: "UK AI research survived mainly at Edinburgh, Essex and Sussex. Large-scale funding returned only with the £350 million Alvey programme (1983), a response to Japan's Fifth Generation project.",
             uk: "Британські дослідження ШІ вижили переважно в Единбурзі, Ессексі та Сассексі. Масштабне фінансування повернулося лише з програмою Alvey на 350 млн фунтів (1983) — відповіддю на японський проєкт комп'ютерів п'ятого покоління."},
   memorable: {en: "Historian Thomas Haigh argues there was \"no first AI winter\": funding was cut at a few elite labs, while the research community almost tripled. The report (dated July 1972) was debated publicly at the Royal Institution on 9 May 1973.",
               uk: "Історик Томас Гейг стверджує, що «першої зими ШІ не було»: фінансування урізали кільком елітним лабораторіям, тоді як дослідницька спільнота майже потроїлася. Звіт (датований липнем 1972 року) публічно обговорювали в Королівському інституті 9 травня 1973 року."},
   numbers: [
     {label: {en: "ACM SIGART members, 1973 → mid-1978", uk: "Членів ACM SIGART, 1973 → середина 1978"}, value: "1,241 → ≈3,500", note: {en: "the AI interest group grew through the \"winter\" (Haigh, 2023)", uk: "група з інтересів у ШІ зростала впродовж «зими» (Гейг, 2023)"}, est: false},
     {label: {en: "DARPA speech-understanding contract cancelled", uk: "Скасований контракт DARPA на розуміння мовлення"}, value: "≈$3M/yr", note: {en: "secondary figure; the programme officially ran 1971–76", uk: "за вторинними джерелами; офіційно програма тривала 1971–76"}, est: true},
     {label: {en: "US machine-translation funding ended after ALPAC (1966)", uk: "Фінансування машинного перекладу в США, припинене після ALPAC (1966)"}, value: "≈$20M", note: {en: "secondary estimate", uk: "оцінка за вторинними джерелами"}, est: true},
     {label: {en: "Alvey programme (1983)", uk: "Програма Alvey (1983)"}, value: "£350M", note: {en: "the UK's response to Japan's Fifth Generation project (secondary)", uk: "відповідь Британії на японський проєкт п'ятого покоління (за вторинними джерелами)"}, est: true}
   ],
   arch: "ARCH-symbolic", significance: 4, confidence: "high", caveat: null,
   sources: ["S-R1-26", "S-R1-27", "S-R1-28"]},

  // ---------------------------------------------------------------- E03 · First AI winter (1974–1979): no dated milestone
  // ---------------------------------------------------------------- E04 · Expert systems and the return of neural networks (1980–1986)
  {id: "M-1980-expert-systems", date: "1980-01", precision: "month", t: 1980.04, era: "E04",
   title: {en: "Expert systems go commercial (R1/XCON)", uk: "Експертні системи виходять на ринок (R1/XCON)"},
   who: {en: "John McDermott — Carnegie Mellon University, for Digital Equipment Corporation. Earlier systems: DENDRAL (Feigenbaum, Buchanan, Lederberg, Djerassi; Stanford, from 1964–65) and MYCIN (Shortliffe and colleagues; Stanford, 1970s)",
         uk: "Джон Макдермотт — Університет Карнегі — Меллона, для Digital Equipment Corporation. Попередники: DENDRAL (Фейгенбаум, Б'юкенен, Ледерберг, Джерассі; Стенфорд, із 1964–65) і MYCIN (Шортліфф і колеги; Стенфорд, 1970-ті)"},
   kind: "system",
   what: {en: "Expert systems store a specialist's know-how as IF–THEN rules, with an inference engine that chains them together. DENDRAL inferred molecular structures from mass spectra and MYCIN recommended antibiotics. R1/XCON, written in the OPS4 rule language and later OPS5, worked out which parts each VAX order needed.",
          uk: "Експертні системи зберігають знання фахівця як правила «ЯКЩО — ТО», а механізм логічного виведення зчіплює їх у ланцюжки. DENDRAL визначала структуру молекул за мас-спектрами, MYCIN радила антибіотики. R1/XCON, написана мовою правил OPS4, а згодом OPS5, визначала, які деталі потрібні для кожного замовлення VAX."},
   why: {en: "This was the first AI to make money at scale, and it set off the 1980s boom. Corporate AI spending passed $1B a year by 1985 (secondary). Japan launched its Fifth Generation project (1982–94, about ¥57B, roughly $320M), DARPA its Strategic Computing Initiative (1983) and the UK the Alvey programme (£350M).",
         uk: "Це був перший ШІ, що заробляв гроші у великих масштабах, і він запустив бум 1980-х. Корпоративні витрати на ШІ перевищили 1 млрд доларів на рік до 1985 року (за вторинними джерелами). Японія запустила проєкт комп'ютерів п'ятого покоління (1982–94, близько 57 млрд єн, приблизно 320 млн доларів), DARPA — Strategic Computing Initiative (1983), а Британія — програму Alvey (350 млн фунтів)."},
   example: {en: "By 1986 XCON had processed 80,000 orders with 95–98% accuracy. Estimated savings for DEC were about $25M a year; other accounts say $40M over six years.",
             uk: "До 1986 року XCON обробила 80 000 замовлень із точністю 95–98 %. Оцінені заощадження DEC — близько 25 млн доларів на рік; за іншими джерелами, 40 млн доларів за шість років."},
   memorable: {en: "McDermott's footnote explains the name \"R1\" as a pun: \"Four years ago I couldn't even say 'knowledge engineer', now I . . .\" (are one). DENDRAL, not XCON, is usually counted as the first expert system; XCON was the first big commercial success.",
               uk: "Виноска Макдермотта пояснює назву «R1» як каламбур: «Чотири роки тому я навіть не міг вимовити “інженер знань”, а тепер я…» (англ. now I are one звучить як «R1»). Першою експертною системою зазвичай вважають DENDRAL, а не XCON; XCON стала першим великим комерційним успіхом."},
   numbers: [
     {label: {en: "Rules in R1 (June 1980)", uk: "Правил у R1 (червень 1980)"}, value: "772", note: {en: "420 components; over 500 orders configured; later about 2,500 rules as XCON", uk: "420 компонентів; понад 500 налаштованих замовлень; пізніше близько 2 500 правил як XCON"}, est: false},
     {label: {en: "Orders processed by 1986", uk: "Оброблених замовлень до 1986 року"}, value: "80,000", note: {en: "95–98% accuracy (secondary)", uk: "точність 95–98 % (за вторинними джерелами)"}, est: false},
     {label: {en: "Estimated savings for DEC", uk: "Оцінені заощадження DEC"}, value: "≈$25M/yr", note: {en: "other accounts say $40M over six years; secondary and inconsistent", uk: "інші джерела називають 40 млн доларів за шість років; вторинні й суперечливі дані"}, est: true},
     {label: {en: "MYCIN choices rated acceptable (1979)", uk: "Рішень MYCIN, визнаних прийнятними (1979)"}, value: "65%", note: {en: "blinded test; Stanford specialists scored 42.5–62.5%; MYCIN was never used in routine care", uk: "сліпий тест; фахівці Стенфорда — 42,5–62,5 %; MYCIN так і не використовували в рутинній практиці"}, est: false}
   ],
   arch: "ARCH-symbolic", significance: 4, confidence: "high", caveat: null,
   sources: ["S-R1-29", "S-R1-30", "S-R1-31", "S-R1-32", "S-R1-33", "S-R1-27"]},

  {id: "M-1986-backprop", date: "1986-10-09", precision: "day", t: 1986.77, era: "E04",
   title: {en: "Backpropagation popularised", uk: "Популяризація зворотного поширення помилки"},
   who: {en: "David E. Rumelhart (UC San Diego), Geoffrey E. Hinton (Carnegie Mellon), Ronald J. Williams (UC San Diego). Earlier roots: Seppo Linnainmaa (1970), Paul Werbos (1974, 1982), David Parker and Yann LeCun (1985), Shun'ichi Amari (1967)",
         uk: "Девід Румельгарт (Каліфорнійський університет у Сан-Дієго), Джеффрі Гінтон (Карнегі — Меллон), Рональд Вільямс (Каліфорнійський університет у Сан-Дієго). Ранні корені: Сеппо Ліннайнмаа (1970), Пол Вербос (1974, 1982), Девід Паркер і Ян Лекун (1985), Сюн'їті Амарі (1967)"},
   kind: "paper",
   what: {en: "The output error is sent backwards through a multilayer network, and the chain rule gives each weight its exact share of the blame. The four-page paper showed that the hidden units then learn useful internal features of their own.",
          uk: "Помилку на виході пропускають назад крізь багатошарову мережу, і ланцюгове правило дає кожній вазі її точну частку провини. Чотиристорінкова стаття показала, що приховані елементи при цьому самі вивчають корисні внутрішні ознаки."},
   why: {en: "It answered the objection of 1969: networks with hidden layers can be trained. That launched the second neural-network wave (the \"Parallel Distributed Processing\" volumes, also 1986), and today's models are still trained with essentially the same algorithm.",
         uk: "Це відповіло на заперечення 1969 року: мережі з прихованими шарами можна навчати. Так почалася друга хвиля нейронних мереж (томи «Parallel Distributed Processing», теж 1986), і сьогоднішні моделі досі навчають по суті тим самим алгоритмом."},
   example: {en: "NETtalk (Sejnowski & Rosenberg, 1987) was a backpropagation network with 18,629 weights that learned to turn written English into phonemes, which a speech synthesiser read aloud.",
             uk: "NETtalk (Сейновскі та Розенберг, 1987) — мережа зі зворотним поширенням на 18 629 ваг, яка навчилася перетворювати написану англійську на фонеми, а синтезатор мовлення читав їх уголос."},
   memorable: {en: "Linnainmaa's 1970 master's thesis already contained efficient reverse-mode differentiation, with FORTRAN code, 16 years earlier. The 1986 paper did not cite it, and arguments over credit continue (the priority history rests on Schmidhuber's survey and Wikipedia).",
               uk: "Магістерська робота Ліннайнмаа 1970 року вже містила ефективне диференціювання у зворотному режимі, з кодом на FORTRAN, — на 16 років раніше. Стаття 1986 року її не цитувала, і суперечки про першість тривають (історія пріоритету спирається на огляд Шмідгубера та Wikipedia)."},
   numbers: [
     {label: {en: "Pages", uk: "Сторінок"}, value: "4", note: {en: "Nature 323, 9 October 1986", uk: "Nature 323, 9 жовтня 1986"}, est: false},
     {label: {en: "NETtalk weights (1987)", uk: "Ваг у NETtalk (1987)"}, value: "18,629", note: {en: "a backpropagation network that learned to read English aloud", uk: "мережа зі зворотним поширенням, яка навчилася читати англійську вголос"}, est: false},
     {label: {en: "NETtalk training compute", uk: "Обчислення для навчання NETtalk"}, value: "~10¹⁰ FLOP", note: {en: "reconstructed est. (Epoch AI): about 2.8×10¹⁰ FLOP", uk: "реконструйована оцінка (Epoch AI): близько 2,8×10¹⁰ FLOP"}, est: true},
     {label: {en: "Linnainmaa's thesis with reverse-mode differentiation", uk: "Робота Ліннайнмаа зі зворотним режимом диференціювання"}, value: "1970", note: {en: "published 1976; Werbos 1974 and 1982; Parker and LeCun 1985", uk: "опубліковано 1976; Вербос 1974 і 1982; Паркер і Лекун 1985"}, est: false}
   ],
   arch: "ARCH-mlp-backprop", significance: 5, confidence: "high", caveat: null,
   sources: ["S-R1-37", "S-R1-38", "S-R1-39", "S-R1-40", "S-R1-19"]},

  // ---------------------------------------------------------------- E05 · Second AI winter (1987–1992)
  {id: "M-1987-lisp-machine-collapse", date: "1987", precision: "year", t: 1987.50, era: "E05",
   title: {en: "Lisp-machine collapse: the second AI winter", uk: "Крах Lisp-машин: друга «зима ШІ»"},
   who: {en: "Symbolics, Lisp Machines Inc. (LMI), Texas Instruments, Xerox; DARPA's computing office (IPTO) under Jack Schwarz",
         uk: "Symbolics, Lisp Machines Inc. (LMI), Texas Instruments, Xerox; обчислювальне управління DARPA (IPTO) під керівництвом Джека Шварца"},
   kind: "event",
   what: {en: "Expensive dedicated AI workstations were undercut by cheaper general-purpose Unix workstations (Sun) and by PCs running Lisp. DARPA cut AI spending in its Strategic Computing Initiative in 1987–88. Many expert systems turned out to be brittle and costly to maintain.",
          uk: "Дорогі спеціалізовані робочі станції для ШІ витіснили дешевші універсальні Unix-станції (Sun) і персональні комп'ютери з Lisp. У 1987–88 роках DARPA скоротила витрати на ШІ у своїй Strategic Computing Initiative. Багато експертних систем виявилися крихкими й дорогими в підтримці."},
   why: {en: "This was the second AI winter (E05). \"AI\" became a label people avoided, and researchers rebranded their work as machine learning, informatics or analytics. Statistical methods filled the gap.",
         uk: "Це була друга «зима ШІ» (E05). «ШІ» став ярликом, якого уникали, а дослідники перейменовували свою роботу на машинне навчання, інформатику чи аналітику. Прогалину заповнили статистичні методи."},
   example: {en: "Symbolics owned symbolics.com, the first .com domain ever registered (15 March 1985), and later went bankrupt. LMI went bankrupt before its K-Machine shipped, and Texas Instruments and Xerox left the market.",
             uk: "Symbolics володіла symbolics.com — першим зареєстрованим доменом .com (15 березня 1985 року) — і згодом збанкрутувала. LMI збанкрутувала ще до виходу своєї K-Machine, а Texas Instruments і Xerox пішли з ринку."},
   memorable: {en: "At the 1984 AAAI meeting, Roger Schank and Marvin Minsky coined \"AI winter\" in a public debate, warning business that a crash was coming. It came three years later.",
               uk: "На зустрічі AAAI 1984 року Роджер Шенк і Марвін Мінський у публічній дискусії запровадили термін «зима ШІ», попереджаючи бізнес про наближення краху. Він настав через три роки."},
   numbers: [
     {label: {en: "Lisp machines sold in total by 1988", uk: "Усього продано Lisp-машин до 1988 року"}, value: "≈7,000", note: {en: "secondary histories (Crevier, Newquist via Wikipedia)", uk: "за вторинними історіями (Крев'є, Ньюквіст через Wikipedia)"}, est: true},
     {label: {en: "Price of a Symbolics LM-2", uk: "Ціна Symbolics LM-2"}, value: "≈$70,000", note: {en: "secondary", uk: "за вторинними джерелами"}, est: true},
     {label: {en: "Strategic Computing Initiative spending by 1985", uk: "Витрати Strategic Computing Initiative до 1985 року"}, value: "$100M", note: {en: "92 projects at 60 institutions (secondary); DARPA cut AI spending in 1987–88", uk: "92 проєкти в 60 установах (за вторинними джерелами); у 1987–88 роках DARPA скоротила витрати на ШІ"}, est: true},
     {label: {en: "Industry replaced within a single year", uk: "Галузь, витіснена за один рік"}, value: "≈$0.5B", note: {en: "\"worth half a billion dollars\", according to a secondary history; an order-of-magnitude figure", uk: "«вартістю пів мільярда доларів», за однією вторинною історією; порядок величини"}, est: true}
   ],
   arch: "ARCH-symbolic", significance: 3, confidence: "medium",
   caveat: {en: "Mostly secondary histories (Crevier and Newquist, via Wikipedia): the sales, price and industry-size figures are order-of-magnitude estimates, and 1987 is the conventional year of the collapse rather than a dated event.",
            uk: "Переважно вторинні історії (Крев'є та Ньюквіст, через Wikipedia): обсяги продажів, ціни й розмір галузі — оцінки порядку величини, а 1987 рік — усталена дата краху, а не датована подія."},
   sources: ["S-R1-41", "S-R1-27"]},

  {id: "M-1989-lecun-cnn", date: "1989-12", precision: "month", t: 1989.95, era: "E05",
   title: {en: "A convolutional network reads zip codes", uk: "Згорткова мережа читає поштові індекси"},
   who: {en: "Yann LeCun, Bernhard Boser, John Denker, Donnie Henderson, Richard Howard, Wayne Hubbard, Lawrence Jackel — AT&T Bell Laboratories, Holmdel",
         uk: "Ян Лекун, Бернхард Бозер, Джон Денкер, Донні Гендерсон, Річард Говард, Вейн Габбард, Лоуренс Джекел — AT&T Bell Laboratories, Голмдел"},
   kind: "architecture",
   what: {en: "Backpropagation trained a network of small, local feature detectors directly on 16×16-pixel digit images. Each detector shares its weights across every position in the image, which is what convolution means. The design built on Fukushima's Neocognitron (1980), which had no end-to-end gradient training.",
          uk: "Зворотне поширення помилки навчило мережу з малих локальних детекторів ознак безпосередньо на зображеннях цифр 16×16 пікселів. Кожен детектор використовує ті самі ваги в усіх позиціях зображення — саме це й означає згортка. Задум спирався на неокогнітрон Фукусіми (1980), який не мав наскрізного градієнтного навчання."},
   why: {en: "It was the first convolutional neural network (CNN) to learn end to end, from raw pixels to labels, on a real-world task. It set the template for every CNN since, including AlexNet (2012).",
         uk: "Це була перша згорткова нейронна мережа (CNN), яка навчалася наскрізно — від сирих пікселів до міток — на реальній задачі. Вона стала шаблоном для всіх наступних CNN, зокрема AlexNet (2012)."},
   example: {en: "The network ran in real time on an AT&T DSP-32C signal-processing chip. Working with NCR, the team went on to build cheque-reading ATMs and bank systems (LeNet-5, 1998).",
             uk: "Мережа працювала в реальному часі на сигнальному процесорі AT&T DSP-32C. Разом із NCR команда згодом створила банкомати й банківські системи для читання чеків (LeNet-5, 1998)."},
   memorable: {en: "The whole network had fewer than 10,000 adjustable numbers. AlexNet, 23 years later, had 60 million.",
               uk: "Уся мережа мала менше ніж 10 000 налаштовуваних чисел. AlexNet через 23 роки мала 60 мільйонів."},
   numbers: [
     {label: {en: "Parameters", uk: "Параметри"}, value: "9,760", note: {en: "1,256 units and 64,660 connections; weights are shared across positions", uk: "1 256 елементів і 64 660 з'єднань; ваги спільні для всіх позицій"}, est: false},
     {label: {en: "Handwritten digits", uk: "Рукописних цифр"}, value: "9,298", note: {en: "from mail passing through the Buffalo, NY post office: 7,291 training / 2,007 test, 16×16 pixels", uk: "з пошти, що проходила через відділення в Баффало (штат Нью-Йорк): 7 291 для навчання / 2 007 для тестування, 16×16 пікселів"}, est: false},
     {label: {en: "Training compute", uk: "Обчислення для навчання"}, value: "~10¹² FLOP", note: {en: "reconstructed est. (Epoch AI): about 1.5×10¹² FLOP; 23 passes over the data", uk: "реконструйована оцінка (Epoch AI): близько 1,5×10¹² FLOP; 23 проходи по даних"}, est: true},
     {label: {en: "Human error on the test digits", uk: "Помилка людей на тестових цифрах"}, value: "≈2.5%", note: {en: "secondary source; the network's own error and reject rates vary by version (about 5% raw, or 1% with 9–12% rejected)", uk: "вторинне джерело; власні показники помилок і відмов мережі різняться залежно від версії (близько 5 % без відмов або 1 % із 9–12 % відмов)"}, est: false}
   ],
   arch: "ARCH-cnn", significance: 4, confidence: "high", caveat: null,
   sources: ["S-R1-42", "S-R1-43", "S-R1-44", "S-R1-19"]},

  // ---------------------------------------------------------------- E06 · Statistical machine learning and the quiet build-up (1993–2011)
  {id: "M-1995-svm", date: "1995-09", precision: "month", t: 1995.70, era: "E06",
   title: {en: "Support-vector machines", uk: "Метод опорних векторів (SVM)"},
   who: {en: "Corinna Cortes, Vladimir Vapnik — AT&T Bell Laboratories; builds on the kernel trick of Boser, Guyon & Vapnik (1992) and on Vapnik & Chervonenkis's maximum-margin method (1960s)",
         uk: "Корінна Кортес, Володимир Вапник — AT&T Bell Laboratories; спирається на ядровий трюк Бозера, Гійон і Вапника (1992) та метод максимального зазору Вапника і Червоненкіса (1960-ті)"},
   kind: "paper",
   what: {en: "An SVM finds the boundary that leaves the widest possible gap (\"margin\") between two classes. The \"kernel trick\" lets it draw curved boundaries cheaply. Cortes and Vapnik added the \"soft margin\", which tolerates noisy, overlapping data.",
          uk: "SVM знаходить межу, що залишає якнайширший проміжок («зазор») між двома класами. «Ядровий трюк» дає змогу дешево проводити криві межі. Кортес і Вапник додали «м'який зазор», який терпить зашумлені дані, що перекриваються."},
   why: {en: "Training is a convex problem with a single best answer, it rests on solid theory, and it needs little tuning. From the late 1990s until about 2011, SVMs and related kernel methods outperformed neural networks on most benchmarks, which pushed neural nets to the margins.",
         uk: "Навчання — опукла задача з єдиним найкращим розв'язком, воно спирається на міцну теорію й майже не потребує налаштування. З кінця 1990-х до приблизно 2011 року SVM та споріднені ядрові методи перевершували нейронні мережі на більшості бенчмарків, що відсунуло нейромережі на узбіччя."},
   example: {en: "On MNIST, an SVM with a degree-4 polynomial kernel scored 1.1% error and a \"virtual SVM\" 0.8%, matching LeNet-5's 0.8% (trained with distorted images) without any built-in knowledge of images. The winners of ImageNet's 2010 and 2011 challenges were SVM-based.",
             uk: "На MNIST SVM із поліноміальним ядром 4-го степеня дав 1,1 % помилок, а «віртуальний SVM» — 0,8 %, нарівні з 0,8 % у LeNet-5 (навченої на спотворених зображеннях), без жодних вбудованих знань про зображення. Переможці змагань ImageNet 2010 і 2011 років базувалися на SVM."},
   memorable: {en: "The core maximum-margin idea came from Soviet work in the early 1960s (secondary sources). It took about 30 years, plus the kernel trick, to become the field's favourite tool.",
               uk: "Основна ідея максимального зазору походить із радянських робіт початку 1960-х (за вторинними джерелами). Їй знадобилося близько 30 років і ядровий трюк, щоб стати улюбленим інструментом галузі."},
   numbers: [
     {label: {en: "MNIST error, SVM with a degree-4 polynomial kernel", uk: "Помилка на MNIST, SVM із поліноміальним ядром 4-го степеня"}, value: "1.1%", note: {en: "a \"virtual SVM\" (degree 9) reached 0.8%, matching LeNet-5 trained with distorted images (LeCun et al., 1998)", uk: "«віртуальний SVM» (9-й степінь) досяг 0,8 %, нарівні з LeNet-5, навченою на спотворених зображеннях (Лекун та ін., 1998)"}, est: false},
     {label: {en: "ILSVRC 2010 winning top-5 error (SVM-based)", uk: "Переможна помилка top-5 на ILSVRC 2010 (на основі SVM)"}, value: "28.2%", note: {en: "NEC: SIFT/LBP features + SVM; in 2011 XRCE scored 25.8% with Fisher vectors + a linear SVM", uk: "NEC: ознаки SIFT/LBP + SVM; у 2011 році XRCE — 25,8 % із векторами Фішера та лінійним SVM"}, est: false},
     {label: {en: "Years from the maximum-margin idea to the soft-margin SVM", uk: "Років від ідеї максимального зазору до SVM із м'яким зазором"}, value: "≈30", note: {en: "early 1960s (Vapnik & Chervonenkis) to 1995; the origin rests on secondary sources", uk: "з початку 1960-х (Вапник і Червоненкіс) до 1995 року; походження — за вторинними джерелами"}, est: true}
   ],
   arch: null, significance: 4, confidence: "high", caveat: null,
   sources: ["S-R1-48", "S-R1-49", "S-R1-57", "S-R1-67"]},

  {id: "M-1997-deep-blue", date: "1997-05-11", precision: "day", t: 1997.36, era: "E06",
   title: {en: "Deep Blue defeats Kasparov", uk: "Deep Blue перемагає Каспарова"},
   who: {en: "Feng-hsiung Hsu, Murray Campbell, A. Joseph Hoane Jr., C. J. Tan and team — IBM Research",
         uk: "Фен-сюн Сюй, Мюррей Кемпбелл, А. Джозеф Гоун-молодший, К. Дж. Тан і команда — IBM Research"},
   kind: "system",
   what: {en: "Deep Blue was a custom IBM RS/6000 SP supercomputer with 480 dedicated chess chips. It searched about 200 million positions a second, using alpha-beta search (exploring moves while pruning lines that cannot matter) and a hand-tuned evaluation function with over 8,000 features, together with an opening book and endgame databases. It won the match 3½–2½.",
          uk: "Deep Blue був спеціально зібраним суперкомп'ютером IBM RS/6000 SP із 480 шаховими чипами. Він перебирав близько 200 млн позицій за секунду, використовуючи альфа-бета-пошук (розгляд ходів із відсіканням варіантів, які не можуть мати значення) і налаштовану вручну оцінну функцію з понад 8 000 ознак, а також дебютну книгу та бази ендшпілів. Матч він виграв з рахунком 3½–2½."},
   why: {en: "It was the first computer to defeat a reigning world champion in a match under standard tournament time controls. It was a triumph of search and special hardware, not of learning: no neural network was involved.",
         uk: "Це був перший комп'ютер, що переміг чинного чемпіона світу в матчі зі стандартним турнірним контролем часу. Тріумф пошуку й спеціалізованого заліза, а не навчання: жодної нейронної мережі там не було."},
   example: {en: "In February 1996 Kasparov won their first match 4–2, although Deep Blue took game 1, the first win by a computer against a reigning champion at classical time controls. IBM doubled the machine's speed and won the 1997 rematch.",
             uk: "У лютому 1996 року Каспаров виграв перший матч 4–2, хоча Deep Blue взяв першу партію — перша перемога комп'ютера над чинним чемпіоном із класичним контролем часу. IBM удвічі збільшила швидкість машини й виграла матч-реванш 1997 року."},
   memorable: {en: "Kasparov: \"For the first time in the history of mankind, I saw something similar to an artificial intellect.\"",
               uk: "Каспаров: «Уперше в історії людства я побачив щось схоже на штучний інтелект»."},
   numbers: [
     {label: {en: "Positions searched per second", uk: "Позицій за секунду"}, value: "≈200M", note: {en: "IBM's figure, twice the 1996 machine; other technical accounts give about 100–200M during play", uk: "дані IBM, удвічі більше за машину 1996 року; інші технічні джерела дають близько 100–200 млн під час гри"}, est: false},
     {label: {en: "Custom chess chips", uk: "Спеціалізованих шахових чипів"}, value: "480", note: {en: "30 nodes with 200 MHz PowerPC 604e processors; no neural network", uk: "30 вузлів із процесорами PowerPC 604e на 200 МГц; жодної нейронної мережі"}, est: false},
     {label: {en: "Match result", uk: "Рахунок матчу"}, value: "3½–2½", note: {en: "New York, 3–11 May 1997; Kasparov had won the February 1996 match 4–2", uk: "Нью-Йорк, 3–11 травня 1997 р.; у лютому 1996 року Каспаров виграв перший матч 4–2"}, est: false},
     {label: {en: "LINPACK performance", uk: "Продуктивність за LINPACK"}, value: "11.38 GFLOPS", note: {en: "TOP500 list, June 1997", uk: "список TOP500, червень 1997"}, est: false}
   ],
   arch: "ARCH-symbolic", significance: 4, confidence: "high", caveat: null,
   sources: ["S-R1-50", "S-R1-51", "S-R1-52", "S-R1-19"]},

  {id: "M-1997-lstm", date: "1997-11", precision: "month", t: 1997.87, era: "E06",
   title: {en: "Long Short-Term Memory", uk: "Довга короткочасна пам'ять (LSTM)"},
   who: {en: "Sepp Hochreiter (TU Munich), Jürgen Schmidhuber (IDSIA, Lugano)",
         uk: "Зепп Гохрайтер (Технічний університет Мюнхена), Юрген Шмідгубер (IDSIA, Лугано)"},
   kind: "architecture",
   what: {en: "LSTM is a recurrent network (one that processes sequences step by step) built from memory cells. Inside each cell a \"constant error carousel\" lets error signals flow back unchanged across long gaps, and multiplicative input and output gates learn when to write to the memory and when to read from it.",
          uk: "LSTM — це рекурентна мережа (яка обробляє послідовності крок за кроком), побудована з комірок пам'яті. Усередині кожної комірки «карусель сталої помилки» дає сигналам помилки проходити назад без змін через довгі проміжки, а мультиплікативні вхідний і вихідний вентилі вчаться, коли писати в пам'ять і коли з неї читати."},
   why: {en: "It addressed the vanishing-gradient problem. Hochreiter had analysed that problem in his 1991 thesis, and Bengio, Simard and Frasconi did so independently in 1994: learning signals in ordinary recurrent networks fade over long sequences. LSTM became the standard sequence model for speech, handwriting and translation until transformers arrived in 2017.",
         uk: "Вона розв'язала проблему зникаючого градієнта. Гохрайтер проаналізував її у своїй дипломній роботі 1991 року, а Бенджіо, Сімар і Фрасконі — незалежно у 1994-му: у звичайних рекурентних мережах сигнали навчання згасають на довгих послідовностях. LSTM стала стандартною моделлю послідовностей для мовлення, рукописного тексту й перекладу, доки 2017 року не з'явилися трансформери."},
   example: {en: "In August 2015 Google reported that switching Google Voice transcription to LSTM networks brought the recognition error rate down to roughly half that of the original system.",
             uk: "У серпні 2015 року Google повідомила, що перехід транскрипції Google Voice на мережі LSTM знизив частоту помилок розпізнавання приблизно вдвічі порівняно з початковою системою."},
   memorable: {en: "The 1997 LSTM had no forget gate, so it could not learn to clear its own memory. The gate that every diagram now shows came from Gers, Schmidhuber & Cummins (2000).",
               uk: "LSTM 1997 року не мала вентиля забування, тож не могла навчитися очищати власну пам'ять. Вентиль, який тепер є на кожній схемі, додали Герс, Шмідгубер і Каммінс (2000)."},
   numbers: [
     {label: {en: "Time steps bridged", uk: "Кроків часу, через які проходить сигнал"}, value: ">1,000", note: {en: "ordinary recurrent networks lose the learning signal over long gaps (vanishing gradient)", uk: "звичайні рекурентні мережі втрачають сигнал навчання на довгих проміжках (зникаючий градієнт)"}, est: false},
     {label: {en: "Parameters (largest 1997 experiment)", uk: "Параметри (найбільший експеримент 1997 року)"}, value: "≈10,504", note: {en: "Epoch AI estimate", uk: "оцінка Epoch AI"}, est: true},
     {label: {en: "Training compute", uk: "Обчислення для навчання"}, value: "3.2×10¹³ FLOP", note: {en: "Epoch AI estimate", uk: "оцінка Epoch AI"}, est: true},
     {label: {en: "Google Voice error rate after switching to LSTM (2015)", uk: "Частота помилок Google Voice після переходу на LSTM (2015)"}, value: "≈½", note: {en: "roughly half that of the original system (Google's own figure)", uk: "приблизно половина від початкової системи (за даними самої Google)"}, est: false}
   ],
   arch: "ARCH-rnn-lstm", significance: 4, confidence: "high", caveat: null,
   sources: ["S-R1-53", "S-R1-54", "S-R1-55", "S-R1-56", "S-R1-19"]},

  {id: "M-2006-deep-belief-nets", date: "2006-07", precision: "month", t: 2006.53, era: "E06",
   title: {en: "Deep belief nets revive deep learning", uk: "Глибокі мережі переконань відроджують глибинне навчання"},
   who: {en: "Geoffrey Hinton, Simon Osindero (University of Toronto), Yee-Whye Teh (National University of Singapore); Science paper with Ruslan Salakhutdinov",
         uk: "Джеффрі Гінтон, Саймон Осіндеро (Університет Торонто), Ї-Вай Те (Національний університет Сінгапуру); стаття в Science — з Русланом Салахутдіновим"},
   kind: "paper",
   what: {en: "The network is trained one layer at a time. Each layer is a restricted Boltzmann machine that learns to model the layer beneath it, and the whole stack is then fine-tuned. The paper's 784-500-500-2000 network, with 10 label units, learned to both generate and classify handwritten digits.",
          uk: "Мережу навчають по одному шару за раз. Кожен шар — обмежена машина Больцмана, яка вчиться моделювати шар під собою, а потім увесь стос донавчають. Мережа зі статті 784-500-500-2000 із 10 елементами для міток навчилася і породжувати, і класифікувати рукописні цифри."},
   why: {en: "It showed that deep networks could be trained after years of failure, and it helped bring the label \"deep learning\" into use. Within five years, deep nets pre-trained this way were beating the best speech recognisers.",
         uk: "Це показало, що глибокі мережі можна навчати після років невдач, і допомогло ввести в ужиток термін «глибинне навчання». За п'ять років глибокі мережі з таким попереднім навчанням перевершували найкращі системи розпізнавання мовлення."},
   example: {en: "Microsoft Research (Seide, Li & Yu, Interspeech, August 2011) used deep belief net pre-training for networks with up to 9 hidden layers, trained on more than 300 hours of telephone speech. Word error on the Switchboard benchmark fell from 27.4% to 18.5%, a 33% relative reduction.",
             uk: "Microsoft Research (Зайде, Лі та Ю, Interspeech, серпень 2011) використала попереднє навчання глибоких мереж переконань для мереж із до 9 прихованими шарами, навчених на понад 300 годинах телефонного мовлення. Частота помилок у словах на бенчмарку Switchboard впала з 27,4 % до 18,5 % — відносне зменшення на 33 %."},
   memorable: {en: "The network that restarted deep learning was trained on a single desktop processor, in Matlab.",
               uk: "Мережу, яка перезапустила глибинне навчання, навчили на одному настільному процесорі, у Matlab."},
   numbers: [
     {label: {en: "MNIST error", uk: "Помилка на MNIST"}, value: "1.25%", note: {en: "against 1.5% for the best backpropagation nets and 1.4% for SVMs at the time", uk: "проти 1,5 % у найкращих мереж зі зворотним поширенням і 1,4 % у SVM на той час"}, est: false},
     {label: {en: "Network layers", uk: "Шари мережі"}, value: "784-500-500-2000", note: {en: "plus 10 label units; each layer a restricted Boltzmann machine trained one at a time", uk: "плюс 10 елементів для міток; кожен шар — обмежена машина Больцмана, навчена окремо"}, est: false},
     {label: {en: "Parameters", uk: "Параметри"}, value: "≈1.6M", note: {en: "Epoch AI estimate; about a week of training in Matlab on one 3 GHz Xeon CPU", uk: "оцінка Epoch AI; близько тижня навчання в Matlab на одному процесорі Xeon 3 ГГц"}, est: true},
     {label: {en: "Switchboard word error rate (Microsoft, 2011)", uk: "Частота помилок у словах на Switchboard (Microsoft, 2011)"}, value: "27.4% → 18.5%", note: {en: "a 33% relative reduction; up to 9 hidden layers, 300+ hours of telephone speech", uk: "відносне зменшення на 33 %; до 9 прихованих шарів, понад 300 годин телефонного мовлення"}, est: false}
   ],
   arch: "ARCH-mlp-backprop", significance: 4, confidence: "high", caveat: null,
   sources: ["S-R1-59", "S-R1-60", "S-R1-61", "S-R1-19"]},

  {id: "M-2009-imagenet", date: "2009-06", precision: "month", t: 2009.45, era: "E06",
   title: {en: "ImageNet", uk: "ImageNet"},
   who: {en: "Jia Deng, Wei Dong, Richard Socher, Li-Jia Li, Kai Li, Li Fei-Fei — Princeton University",
         uk: "Цзя Ден, Вей Дун, Річард Сочер, Лі-Цзя Лі, Кай Лі, Фей-Фей Лі — Принстонський університет"},
   kind: "dataset",
   what: {en: "ImageNet organises images by the noun categories (\"synsets\") of the WordNet dictionary. Crowd workers on Amazon Mechanical Turk checked the labels. The 2009 paper already held 3.2 million images in 5,247 categories, against a goal of about 50 million.",
          uk: "ImageNet упорядковує зображення за іменниковими категоріями («синсетами») словника WordNet. Мітки перевіряли краудсорсингові працівники на Amazon Mechanical Turk. У статті 2009 року вже було 3,2 млн зображень у 5 247 категоріях, за мети близько 50 млн."},
   why: {en: "It supplied data at the scale deep networks needed, and a public yardstick for measuring them. The annual ImageNet Large Scale Visual Recognition Challenge (ILSVRC, from 2010, 1,000 classes) is where AlexNet broke through in 2012.",
         uk: "Він дав дані в масштабі, якого потребували глибокі мережі, і публічну мірку для їх оцінювання. Саме на щорічному змаганні ImageNet Large Scale Visual Recognition Challenge (ILSVRC, з 2010 року, 1 000 класів) у 2012 році стався прорив AlexNet."},
   example: {en: "Winning top-5 error in the ILSVRC classification task: 28.2% in 2010 (NEC), 25.8% in 2011 (XRCE), then 16.4% in 2012 for AlexNet, entered as \"SuperVision\" (15.3% with extra training data), against 26.2% for second place.",
             uk: "Переможна помилка top-5 у класифікаційній задачі ILSVRC: 28,2 % у 2010 році (NEC), 25,8 % у 2011-му (XRCE), а потім 16,4 % у 2012-му в AlexNet, заявленої як «SuperVision» (15,3 % із додатковими навчальними даними), проти 26,2 % у другого місця."},
   memorable: {en: "Li began the project in 2006, when most researchers saw algorithms, not data, as the bottleneck. By 2012 ImageNet was reportedly the largest academic user of Mechanical Turk.",
               uk: "Лі розпочала проєкт 2006 року, коли більшість дослідників вважали вузьким місцем алгоритми, а не дані. До 2012 року ImageNet, за повідомленнями, був найбільшим академічним користувачем Mechanical Turk."},
   numbers: [
     {label: {en: "Images in the 2009 paper", uk: "Зображень у статті 2009 року"}, value: "3.2M", note: {en: "5,247 categories; goal about 50 million", uk: "5 247 категорій; мета — близько 50 млн"}, est: false},
     {label: {en: "Images by April 2010", uk: "Зображень до квітня 2010 року"}, value: "14.2M", note: {en: "14,197,122 images in 21,841 categories; ImageNet-1K training set 1,281,167", uk: "14 197 122 зображення у 21 841 категорії; навчальний набір ImageNet-1K — 1 281 167"}, est: false},
     {label: {en: "Label precision", uk: "Точність міток"}, value: "≈99.7%", note: {en: "on sampled categories; labels checked by Mechanical Turk workers", uk: "на вибіркових категоріях; мітки перевіряли працівники Mechanical Turk"}, est: false},
     {label: {en: "Crowd workers", uk: "Краудсорсингових працівників"}, value: "49,000", note: {en: "in 167 countries, July 2008 to April 2010, as reported by the project's founder (secondary)", uk: "у 167 країнах, з липня 2008 до квітня 2010 року, за словами засновниці проєкту (вторинне джерело)"}, est: false}
   ],
   arch: "ARCH-cnn", significance: 5, confidence: "high", caveat: null,
   sources: ["S-R1-66", "S-R1-67", "S-R1-68"]},

  {id: "M-2009-gpu-deep-learning", date: "2009-06-14", precision: "day", t: 2009.45, era: "E06",
   title: {en: "GPUs for deep learning", uk: "GPU для глибинного навчання"},
   who: {en: "Rajat Raina, Anand Madhavan, Andrew Y. Ng — Stanford University; Ian Buck, John Nickolls and team — NVIDIA (CUDA)",
         uk: "Раджат Райна, Ананд Мадгаван, Ендрю Ин — Стенфордський університет; Ієн Бак, Джон Ніколлс і команда — NVIDIA (CUDA)"},
   kind: "hardware",
   what: {en: "CUDA (public beta SDK 16 February 2007) let programmers write ordinary C code for graphics chips. Raina et al. showed that deep belief nets trained up to 70× faster on one GeForce GTX 280 graphics card than on a dual-core CPU. A 4-layer network with 100 million parameters went from \"several weeks\" of training to \"around a single day\".",
          uk: "CUDA (публічна бета SDK — 16 лютого 2007 року) дала програмістам змогу писати звичайний код мовою C для графічних чипів. Райна зі співавторами показали, що глибокі мережі переконань навчаються до 70 разів швидше на одній відеокарті GeForce GTX 280, ніж на двоядерному CPU. Чотиришарова мережа зі 100 млн параметрів перейшла від «кількох тижнів» навчання до «приблизно одного дня»."},
   why: {en: "Compute had been the missing ingredient. GPUs led directly to AlexNet, trained on two GTX 580 cards in 2012, and to the GPU-centred economics of AI ever since.",
         uk: "Бракувало саме обчислень. GPU привели напряму до AlexNet, навченої 2012 року на двох картах GTX 580, і до економіки ШІ, зосередженої навколо GPU, відтоді й дотепер."},
   example: {en: "IDSIA in Switzerland (Cireşan et al.) trained a plain multilayer network on GPUs to a record 0.35% error on MNIST in 2010. In 2011 their GPU-trained CNN committees outperformed humans \"by a factor of two\" on a German traffic-sign benchmark.",
             uk: "Швейцарська IDSIA (Чірешан та ін.) у 2010 році навчила на GPU звичайну багатошарову мережу до рекордних 0,35 % помилок на MNIST. У 2011 році їхні комітети згорткових мереж, навчені на GPU, перевершили людей «удвічі» на німецькому бенчмарку дорожніх знаків."},
   memorable: {en: "In three years the largest deep belief nets grew about 60-fold, from 1.6M parameters (Hinton, 2006) to 100M (Raina, 2009), mostly because of a gaming graphics card.",
               uk: "За три роки найбільші глибокі мережі переконань виросли приблизно в 60 разів — з 1,6 млн параметрів (Гінтон, 2006) до 100 млн (Райна, 2009) — здебільшого завдяки ігровій відеокарті."},
   numbers: [
     {label: {en: "Speed-up over a dual-core CPU", uk: "Прискорення порівняно з двоядерним CPU"}, value: "70×", note: {en: "up to 70× on one GeForce GTX 280 (240 cores, 1 GB memory)", uk: "до 70 разів на одній GeForce GTX 280 (240 ядер, 1 ГБ пам'яті)"}, est: false},
     {label: {en: "Parameters", uk: "Параметри"}, value: "100M", note: {en: "a 4-layer deep belief net: from \"several weeks\" of training to \"around a single day\"", uk: "чотиришарова глибока мережа переконань: від «кількох тижнів» навчання до «приблизно одного дня»"}, est: false},
     {label: {en: "Training compute", uk: "Обчислення для навчання"}, value: "~10¹⁵ FLOP", note: {en: "Epoch AI estimate", uk: "оцінка Epoch AI"}, est: true},
     {label: {en: "MNIST error on GPUs (IDSIA, 2010)", uk: "Помилка на MNIST на GPU (IDSIA, 2010)"}, value: "0.35%", note: {en: "a plain multilayer network; in 2011 IDSIA's GPU CNN committees beat humans \"by a factor of two\" on German traffic signs", uk: "звичайна багатошарова мережа; у 2011 році комітети GPU-CNN від IDSIA перевершили людей «удвічі» на німецьких дорожніх знаках"}, est: false}
   ],
   arch: "ARCH-cnn", significance: 4, confidence: "high", caveat: null,
   sources: ["S-R1-62", "S-R1-63", "S-R1-64", "S-R1-65", "S-R1-19"]}
);

